{"solution_py":""""Parse an HTTP Retry-After value."""
from __future__ import annotations

from datetime import datetime
from email.utils import format_datetime, parsedate_to_datetime


def parse_retry_after(value: str, *, now: datetime, max_delay: int) -> int | None:
    """Return the Retry-After delay in seconds, or None if invalid."""
    if not isinstance(value, str) or not isinstance(max_delay, int):
        return None

    limit = max(0, max_delay)
    text = value.strip()

    if text and all("0" <= char <= "9" for char in text):
        try:
            return min(int(text), limit)
        except (ValueError, OverflowError):
            return None

    try:
        retry_at = parsedate_to_datetime(text)
        if retry_at is None or format_datetime(retry_at, usegmt=True) != text:
            return None
        if now.tzinfo is None or now.utcoffset() is None:
            return None
        delay = int((retry_at - now).total_seconds())
    except (TypeError, ValueError, OverflowError):
        return None

    return min(max(0, delay), limit)
