{"solution_py":""""Parse an HTTP Retry-After value."""
from __future__ import annotations

from datetime import datetime, timezone
import re


_DELTA = re.compile(r"[0-9]+\Z")
_DATE = re.compile(
    r"(?P<wday>Mon|Tue|Wed|Thu|Fri|Sat|Sun), "
    r"(?P<day>[0-9]{2}) "
    r"(?P<mon>Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) "
    r"(?P<year>[0-9]{4}) "
    r"(?P<hour>[0-9]{2}):(?P<minute>[0-9]{2}):(?P<second>[0-9]{2}) GMT\Z"
)

_MONTHS = {
    name: number
    for number, name in enumerate(
        ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"),
        1,
    )
}
_WEEKDAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")


def parse_retry_after(value: str, *, now: datetime, max_delay: int) -> int | None:
    """Return the delay represented by a Retry-After header, or None."""
    if not isinstance(value, str):
        return None

    text = value.strip()
    if _DELTA.fullmatch(text):
        delay = int(text)
    else:
        match = _DATE.fullmatch(text)
        if match is None:
            return None
        try:
            target = datetime(
                int(match.group("year")),
                _MONTHS[match.group("mon")],
                int(match.group("day")),
                int(match.group("hour")),
                int(match.group("minute")),
                int(match.group("second")),
                tzinfo=timezone.utc,
            )
        except ValueError:
            return None
        if _WEEKDAYS[target.weekday()] != match.group("wday"):
            return None
        if now.tzinfo is None or now.utcoffset() is None:
            return None
        elapsed = target - now
        delay = elapsed.days * 86400 + elapsed.seconds
        if delay < 0:
            delay = 0

    return min(delay, max(0, max_delay))
